21	/// This macro provides a shorthand for broadcasting the transaction to the
22	/// network.
23	///
24	/// See: <https://docs.rs/alloy-contract/0.8.3/alloy_contract/struct.CallBuilder.html>
25	///
26	/// # Examples
27	///
28	/// ```rust,ignore
29	/// #[e2e::test]
30	/// async fn foo(alice: Account) -> eyre::Result<()> {
31	///     let contract_addr = alice.as_deployer().deploy().await?.contract_address;
32	///     let contract = Erc721::new(contract_addr, &alice.wallet);
