7	/// Possible panic codes for a revert.
8	///
9	/// Taken from <https://github.com/NomicFoundation/hardhat/blob/main/packages/hardhat-chai-matchers/src/internal/reverted/panic.ts>
10	#[derive(Debug)]
11	#[allow(missing_docs)] // Pretty straightforward variant names.
12	pub enum PanicCode {
13	    AssertionError = 0x1,
14	    ArithmeticOverflow = 0x11,
15	    DivisionByZero = 0x12,
16	    EnumConversionOutOfBounds = 0x21,
17	    IncorrectlyEncodedStorageByteArray = 0x22,
18	    PopOnEmptyArray = 0x31,
19	    ArrayAccessOutOfBounds = 0x32,
20	    TooMuchMemoryAllocated = 0x41,
21	    ZeroInitializedVariable = 0x51,
22	}
23	
24	impl core::fmt::Display for PanicCode {
25	    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
26	        let msg = match self {
27	            PanicCode::AssertionError =>
28	                "Assertion error",
29	            PanicCode::ArithmeticOverflow =>
30	                "Arithmetic operation overflowed outside of an unchecked block",
31	            PanicCode::DivisionByZero =>
32	                "Division or modulo division by zero",
33	            PanicCode::EnumConversionOutOfBounds =>
34	                "Tried to convert a value into an enum, but the value was too big or negative",
35	            PanicCode::IncorrectlyEncodedStorageByteArray =>
36	                "Incorrectly encoded storage byte array",
37	            PanicCode::PopOnEmptyArray =>
38	                ".pop() was called on an empty array",
39	            PanicCode::ArrayAccessOutOfBounds =>
40	                "Array accessed at an out-of-bounds or negative index",
41	            PanicCode::TooMuchMemoryAllocated =>
42	                "Too much memory was allocated, or an array was created that is too large",
43	            PanicCode::ZeroInitializedVariable =>
44	                "Called a zero-initialized variable of internal function type"
45	        };
46	
47	        write!(f, "{msg}")
48	    }
49	}
