51	/// An error representing a panic.
52	pub trait Panic {
53	    /// Checks that `Self` corresponds to a panic with code `code`.
54	    fn panicked_with(&self, code: PanicCode) -> bool;
55	}
56	
57	/// An error representing a revert with some data.
58	pub trait Revert<E> {
59	    /// Checks that `Self` corresponds to the typed abi-encoded error
60	    /// `expected`.
61	    fn reverted_with(&self, expected: E) -> bool;
62	}
63	
64	impl Panic for alloy::contract::Error {
65	    fn panicked_with(&self, _code: PanicCode) -> bool {
66	        let Self::TransportError(e) = self else {
67	            return false;
68	        };
69	
70	        // FIXME: right now we cannot have any better error code for Panics
71	        // check `e`:
72	        //  ErrorResp(
73	        //      ErrorPayload {
74	        //          code: -32000,
75	        //          message: "execution reverted",
76	        //          data: None,
77	        //      },
78	        //  )
79	        let payload = e.as_error_resp().expect("should contain payload");
80	        payload.code == -32000 && payload.message == "execution reverted"
81	    }
82	}
83	
84	impl<E: MethodError> Revert<E> for alloy::contract::Error {
85	    fn reverted_with(&self, expected: E) -> bool {
86	        let Self::TransportError(e) = self else {
87	            return false;
88	        };
89	
90	        let raw_value = e
91	            .as_error_resp()
92	            .and_then(|payload| payload.data.clone())
93	            .expect("should extract the error");
94	
95	        let actual = &raw_value.get().trim_matches('"')[2..];
96	        let expected = alloy::hex::encode(expected.encode());
97	        expected == actual
98	    }
99	}
100	
101	impl<E: SolError> Revert<E> for eyre::Report {
102	    fn reverted_with(&self, expected: E) -> bool {
103	        // Generic revert error
104	        let Some(received) = self
105	            .chain()
106	            .find_map(|err| err.downcast_ref::<RpcError<TransportErrorKind>>())
107	        else {
108	            return false;
109	        };
110	        let RpcError::ErrorResp(received) = received else {
111	            return false;
112	        };
113	        let Some(received) = &received.data else {
114	            return false;
115	        };
116	        let expected = alloy::hex::encode(expected.abi_encode());
117	        received.to_string().contains(&expected)
118	    }
119	}
