80	/// A unit struct used as a synchronization mechanism in
81	/// [`SYNC_ACCOUNT_FACTORY`].
82	struct AccountFactory;
83	
84	impl AccountFactory {
85	    /// Get access to the factory in a synchronized manner.
86	    async fn lock() -> MutexGuard<'static, Self> {
87	        /// Since after wallet generation accounts get funded in the nitro test
88	        /// node from a single "god" wallet, we must synchronize account
89	        /// creation (otherwise the nonce will be too low).
90	        static SYNC_ACCOUNT_FACTORY: std::sync::LazyLock<
91	            Mutex<AccountFactory>,
92	        > = std::sync::LazyLock::new(|| Mutex::new(AccountFactory));
93	
94	        SYNC_ACCOUNT_FACTORY.lock().await
95	    }
96	
97	    /// Create new account and fund it via nitro test node access.
98	    ///
99	    /// # Errors
100	    ///
101	    /// May fail if unable to find the path to the node or if funding the newly
102	    /// created account fails.
103	    async fn create() -> eyre::Result<Account> {
104	        let _lock = AccountFactory::lock().await;
105	
106	        let signer = PrivateKeySigner::random();
107	        let addr = signer.address();
108	        fund_account(addr, DEFAULT_FUNDING_ETH)?;
109	
110	        let rpc_url = std::env::var(RPC_URL_ENV_VAR_NAME)
111	            .expect("failed to load RPC_URL var from env")
112	            .parse()
113	            .expect("failed to parse RPC_URL string into a URL");
114	        let wallet = ProviderBuilder::new()
115	            .with_recommended_fillers()
116	            .wallet(EthereumWallet::from(signer.clone()))
117	            .on_http(rpc_url);
118	
119	        Ok(Account { signer, wallet })
120	    }
121	}
