108	    /// See [`Deployer::deploy_wasm()`] for more details.
109	    pub async fn deploy(&self) -> eyre::Result<Receipt> {
110	        let wasm_path = match &self.example_name {
111	            Some(example_name) => get_wasm(example_name.as_str())?,
112	            None => Crate::new()?.wasm,
113	        };
