3	/// Constructor data.
4	pub struct Constructor {
5	    /// Constructor signature.
6	    pub signature: String,
7	    /// Constructor arguments.
8	    pub args: Vec<String>,
9	}
10	
11	/// Helper trait to convert values to string representation.
12	pub trait AbiTypeToString {
13	    /// Stringify ABI type.
14	    fn abi_type_to_string(&self) -> String;
15	}
16	
17	macro_rules! impl_to_arg_string {
18	    ($($abi_type:ident),* $(,)?) => {$(
19	        impl AbiTypeToString for $abi_type {
20	            fn abi_type_to_string(&self) -> String {
21	                self.to_string()
22	            }
23	        }
24	    )*};
25	}
26	
27	impl_to_arg_string!(U256, u64, String, U8, u8, Address);
28	
29	// Special implementation for Bytes
30	impl AbiTypeToString for stylus_sdk::abi::Bytes {
31	    fn abi_type_to_string(&self) -> String {
32	        format!("0x{}", stylus_sdk::hex::encode(self))
33	    }
34	}
35	
36	/// Generates a function selector for the given method and its args.
37	#[macro_export]
38	macro_rules! constructor {
39	    () => {{
40	        $crate::Constructor {
41	            signature: "constructor()".to_string(),
42	            args: vec![],
43	        }
44	    }};
45	
46	    ($first:expr $(, $rest:expr)* $(,)?) => {{
47	        fn get_abi_str<T: stylus_sdk::abi::AbiType>(_: T) -> &'static str {
48	            <T as stylus_sdk::abi::AbiType>::ABI.as_str()
49	        }
50	
51	        let signature_params = {
52	            let mut params = vec![get_abi_str($first)];
53	            $(params.push(get_abi_str($rest));)*
54	            params.join(",")
55	        };
56	
57	        let args = vec![$crate::AbiTypeToString::abi_type_to_string(&$first)$(, $crate::AbiTypeToString::abi_type_to_string(&$rest))*];
58	
59	        $crate::Constructor {
60	            signature: format!("constructor({})", signature_params),
61	            args,
62	        }
63	    }};
64	}
