16	/// Defines an end-to-end test that injects test accounts through parameters.
17	///
18	/// For more information see [`crate::test`].
19	pub(crate) fn test(_attr: &TokenStream, input: TokenStream) -> TokenStream {
20	    let item_fn = parse_macro_input!(input as syn::ItemFn);
21	    let attrs = &item_fn.attrs;
22	    let sig = &item_fn.sig;
23	    let fn_name = &sig.ident;
24	    let fn_return_type = &sig.output;
25	    let fn_stmts = &item_fn.block.stmts;
26	    let fn_args = &sig.inputs;
27	
28	    let account_declarations = fn_args.into_iter().map(|arg| {
29	        let FnArg::Typed(arg) = arg else {
30	            error!(arg, "unexpected receiver argument in test signature");
31	        };
32	        let account_arg_binding = &arg.pat;
33	        let account_ty = &arg.ty;
34	        quote! {
35	            let #account_arg_binding = #account_ty::new().await?;
36	        }
37	    });
38	    quote! {
39	        #( #attrs )*
40	        #[tokio::test]
41	        async fn #fn_name() #fn_return_type {
42	            #( #account_declarations )*
43	            #( #fn_stmts )*
44	        }
45	    }
46	    .into()
47	}
