91	impl Deployer {
92	    pub fn new(rpc_url: String, private_key: String) -> Self {
93	        Self { rpc_url, private_key, ctor: None, example_name: None }
94	    }
95	
96	    /// Sets the constructor to be used during contract deployment.
97	    pub fn with_constructor(mut self, ctor: Constructor) -> Self {
98	        self.ctor = Some(ctor);
99	        self
100	    }
101	
102	    /// Sets the example name to be used during contract deployment.
103	    pub fn with_example_name(mut self, example_name: &str) -> Self {
104	        self.example_name = Some(format!("{example_name}_example"));
105	        self
106	    }
107	
108	    /// See [`Deployer::deploy_wasm()`] for more details.
109	    pub async fn deploy(&self) -> eyre::Result<Receipt> {
110	        let wasm_path = match &self.example_name {
111	            Some(example_name) => get_wasm(example_name.as_str())?,
112	            None => Crate::new()?.wasm,
113	        };
114	
115	        self.deploy_wasm(&wasm_path).await
116	    }
117	
118	    /// Deploy and activate the contract implemented as `#[entrypoint]` in the
119	    /// current crate.
120	    /// Consumes currently configured deployer.
121	    ///
122	    /// # Errors
123	    ///
124	    /// May error if:
125	    ///
126	    /// - Unable to collect information about the crate required for deployment.
127	    /// - `cargo stylus deploy` errors.
128	    pub async fn deploy_wasm(&self, wasm_path: &Path) -> eyre::Result<Receipt> {
129	        let wasm_path = wasm_path.to_str().expect("wasm file should exist");
130	        let mut command = self.create_command(wasm_path);
131	
132	        let output = command
133	            .output()
134	            .context("failed to execute `cargo stylus deploy` command")?;
135	
136	        // Resources for context on the implementation:
137	        // - https://github.com/OffchainLabs/nitro-contracts/blob/c32af127fe6a9124316abebbf756609649ede1f5/src/stylus/StylusDeployer.sol#L10
138	        // - https://github.com/OffchainLabs/nitro/blob/98aefbacd814b002bd93a625edaaa0abd9e0d2f0/arbos/programs/programs.go#L113
139	        if output.status.success() {
140	            self.get_receipt(output).await
141	        } else {
142	            self.parse_deployment_error(output).await
143	        }
144	    }
145	
146	    fn create_command(&self, wasm_path: &str) -> Command {
147	        let mut command = Command::new("cargo");
148	        command
149	            .args(["stylus", "deploy"])
150	            .args(["-e", &self.rpc_url])
151	            .args(["--private-key", &self.private_key])
152	            .args(["--wasm-file", wasm_path])
153	            .args(["--no-verify"]);
154	
155	        // There are 3 possible cases when it comes to invoking constructors:
156	        //      1. No constructor exists on a contract - `self.ctor_args` should
157	        //         be None
158	        //      2. Constructor exists, but accepts no arguments -
159	        //         `self.ctor_args` should be Some(vec![])
160	        //      3. Constructor exists and accepts arguments - `self.ctor_args`
161	        //         should be Some(vec!["arg1", "arg2", ...])
162	        //
163	        // The deployer address and constructor-args must both be set if the
164	        // constructor is to be invoked on a contract. Otherwise,
165	        // neither should be set.
166	        if let Some(ctor) = self.ctor.as_ref() {
167	            let deployer_address = std::env::var(DEPLOYER_ADDRESS)
168	                .expect("deployer address should be set");
169	
170	            command
171	                .args(["--deployer-address", &deployer_address])
172	                .args(["--constructor-signature", &ctor.signature])
173	                .args(
174	                    [&["--constructor-args".to_string()], ctor.args.as_slice()]
175	                        .concat(),
176	                );
177	        }
178	
179	        command
180	    }
181	
182	    /// These are all band-aid solutions for peculiar nitro-testnode behavior
183	    /// (as of commit de8cf4edec0d12e5ef1b7623e54e35ddb579ff0b on branch
184	    /// "v3-support").
185	    async fn parse_deployment_error(
186	        &self,
187	        output: std::process::Output,
188	    ) -> eyre::Result<Receipt> {
189	        let stderr = &String::from_utf8_lossy(&output.stderr);
190	
191	        // Look for the error pattern with hex data
192	        let error_data_regex = Regex::new(r#"data:.+"(0x[a-fA-F0-9]+)""#)
193	            .context("failed to create error data regex")?;
194	
195	        if let Some(captures) = error_data_regex.captures(stderr) {
196	            if let Some(hex_data) = captures.get(1) {
197	                let hex_str = hex_data.as_str();
198	                let hex_str = &hex_str[2..]; // Skip "0x" prefix
199	                let data = hex::decode(hex_str)
200	                    .context(format!("failed to decode hex: {hex_str}"))?;
201	                let error_selector = &data[0..4];
202	
203	                if error_selector == CONTRACT_INITIALIZATION_ERROR_SELECTOR {
204	                    return Err(eyre::Report::new(
205	                        ContractInitializationError {},
206	                    ));
207	                } else if error_selector == PROGRAM_UP_TO_DATE_ERROR_SELECTOR {
208	                    // For some reason, the error here is:
209	                    // ```
210	                    // did not estimate correctly: (code: 3, message: execution reverted: error ProgramUpToDate(), data: Some(String(\"0xcc944bf2\")))
211	                    // ```
212	                    // which is the same as the one handles later (the
213	                    // activation error), but it still contains the stdout that
214	                    // is the same as if the deployment was successful.
215	                    //
216	                    // This is probably some weird nitro-testnode issue, but for
217	                    // now this quick-fix should work.
218	                    return self.get_receipt(output).await;
219	                } else if error_selector == CONTRACT_DEPLOYMENT_ERROR_SELECTOR {
220	                    return Err(eyre::Report::new(ContractDeploymentError {
221	                        bytecode: data[4..].to_vec().into(),
222	                    }));
223	                }
224	                return Err(eyre::eyre!(hex_str.to_string()));
225	            }
226	        }
227	
228	        // The pattern matches the contract address that is preceeded by
229	        // ANSI escape codes (`cargo stylus deploy` outputs colored text).
230	        let activation_error_regex = Regex::new(
231	            r"activate tx reverted (?:\x1B\[[0-9;]*[a-zA-Z])*(0x[a-fA-F0-9]+)",
232	        )
233	        .context("failed to create activation error regex")?;
234	
235	        if let Some(captures) = activation_error_regex.captures(stderr) {
236	            if let Some(tx_hash_match) = captures.get(1) {
237	                let tx_hash = tx_hash_match.as_str();
238	
239	                let tx_hash = TxHash::from_str(tx_hash)
240	                    .context("Failed to parse transaction hash")?;
241	
242	                let provider = ProviderBuilder::new()
243	                    .with_recommended_fillers()
244	                    .wallet(EthereumWallet::from(
245	                        self.private_key.parse::<PrivateKeySigner>()?,
246	                    ))
247	                    .on_http(
248	                        Url::from_str(&self.rpc_url).expect("invalid Url"),
249	                    );
250	
251	                // We extract the address of the contract that was supposed to
252	                // be activated by `StylusDeployer` by getting the transaction
253	                // that `StylusDeployer` sent to Arbitrum `activateProgram`
254	                // precompile and extracting the address used in the transaction
255	                // input.
256	
257	                let tx = provider
258	                    .get_transaction_by_hash(tx_hash)
259	                    .await
260	                    .map_err(|e: RpcError<TransportErrorKind>| {
261	                        eyre::eyre!("RPC error: {}", e)
262	                    })?
263	                    .ok_or_else(|| {
264	                        eyre::eyre!("Transaction receipt not found")
265	                    })?;
266	
267	                let input = tx.input().encode_hex();
268	
269	                // The pattern matches the contract address contained in the
270	                // input
271	                let contract_addr_regex =
272	                    Regex::new(r"[a-fA-F0-9]{8}0+([a-fA-F0-9]{40})$")
273	                        .context("Failed to create contract addr regex")?;
274	
275	                let contract_addr = contract_addr_regex
276	                    .captures(&input)
277	                    .and_then(|cap| cap.get(1))
278	                    .context(format!(
279	                        "No contract address found in input {input}"
280	                    ))?
281	                    .as_str();
282	                let contract_address = Address::from_str(contract_addr)
283	                    .context(format!(
284	                        "Failed to parse contract address from string: {contract_addr}"
285	                    ))?;
286	
287	                // now that we have the contract address, we only need the
288	                // receipt
289	                let receipt = provider
290	                    .get_transaction_receipt(tx_hash)
291	                    .await
292	                    .map_err(|e: RpcError<TransportErrorKind>| {
293	                        eyre::eyre!("RPC error: {}", e)
294	                    })?
295	                    .ok_or_else(|| {
296	                        eyre::eyre!("Transaction receipt not found")
297	                    })?;
298	
299	                return Ok(Receipt { inner: receipt, contract_address });
300	            }
301	        }
302	
303	        Err(eyre::eyre!("Deployment failed: {}", stderr))
304	    }
305	
306	    /// Constructs the receipt struct extracting the necessary receipt and
307	    /// contract address data out of the `cargo stylus deploy` output with the
308	    /// help of regex.
309	    async fn get_receipt(
310	        &self,
311	        output: std::process::Output,
312	    ) -> eyre::Result<Receipt> {
313	        // Convert output to string
314	        let output_str = String::from_utf8_lossy(&output.stdout);
315	
316	        // first we get the contract address
317	
318	        // The pattern matches the contract address that is preceeded by
319	        // ANSI escape codes (`cargo stylus deploy` outputs colored text).
320	        let contract_addr_regex =
321	            Regex::new(r"deployed code at address:\s*(?:\x1B\[[0-9;]*[a-zA-Z])*(0x[a-fA-F0-9]{40})")
322	                .context("Failed to create contract addr regex")?;
323	
324	        let contract_addr = contract_addr_regex
325	            .captures(&output_str)
326	            .and_then(|cap| cap.get(1))
327	            .context(format!(
328	                "No contract address found in output {output_str}"
329	            ))?
330	            .as_str();
331	        let contract_address =
332	            Address::from_str(contract_addr).context(format!(
333	                "Failed to parse contract address from string: {contract_addr}"
334	            ))?;
335	
336	        // Now we extract the transaction hash to fetch to receipt
337	
338	        let tx_hash_regex = Regex::new(r"0x[a-fA-F0-9]{64}")
339	            .context("Failed to create tx hash regex")?;
340	
341	        let tx_hash = tx_hash_regex
342	            .find(&output_str)
343	            .context(format!(
344	                "No transaction hash found in output {output_str}"
345	            ))?
346	            .as_str();
347	        let tx_hash = TxHash::from_str(tx_hash)
348	            .context("Failed to parse transaction hash")?;
349	
350	        // Finally we can fetch the receipt
351	
352	        let provider = ProviderBuilder::new()
353	            .with_recommended_fillers()
354	            .wallet(EthereumWallet::from(
355	                self.private_key.parse::<PrivateKeySigner>()?,
356	            ))
357	            .on_http(Url::from_str(&self.rpc_url).expect("invalid Url"));
358	
359	        let receipt = provider
360	            .get_transaction_receipt(tx_hash)
361	            .await
362	            .map_err(|e: RpcError<TransportErrorKind>| {
363	                eyre::eyre!("RPC error: {}", e)
364	            })?
365	            .ok_or_else(|| eyre::eyre!("Transaction receipt not found"))?;
366	
367	        Ok(Receipt { inner: receipt, contract_address })
368	    }
369	}
