7	/// Extension trait for asserting an event gets emitted.
8	pub trait Ext<E> {
9	    /// Asserts the contract emitted the `expected` event.
10	    fn emits(&self, expected: E) -> bool;
11	}
12	
13	impl<E> Ext<E> for TransactionReceipt
14	where
15	    E: SolEvent,
16	    E: PartialEq,
17	{
18	    fn emits(&self, expected: E) -> bool {
19	        // Extract all events that are the expected type.
20	        self.inner
21	            .logs()
22	            .iter()
23	            .filter_map(|log| log.log_decode().ok())
24	            .map(|log| log.inner.data)
25	            .any(|event| expected == event)
26	    }
27	}
28	
29	impl<E: Debug> Ext<E> for Receipt
30	where
31	    E: SolEvent,
32	    E: PartialEq,
33	{
34	    fn emits(&self, expected: E) -> bool {
35	        self.inner.emits(expected)
36	    }
37	}
