5	/// Shorthand to print nice errors.
6	macro_rules! error {
7	    ($tokens:expr, $($msg:expr),+ $(,)?) => {{
8	        let error = syn::Error::new(syn::spanned::Spanned::span(&$tokens), format!($($msg),+));
9	        return error.to_compile_error().into();
10	    }};
11	    (@ $tokens:expr, $($msg:expr),+ $(,)?) => {{
12	        return Err(syn::Error::new(syn::spanned::Spanned::span(&$tokens), format!($($msg),+)))
13	    }};
